import{_ as t,o,c as d,ag as a}from"./chunks/framework.D1z9wg1y.js";const p=JSON.parse('{"title":"Adapting the profile","description":"","frontmatter":{},"headers":[],"relativePath":"profile.md","filePath":"profile.md"}'),l={name:"profile.md"};function s(n,e,i,c,r,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="adapting-the-profile" tabindex="-1">Adapting the profile <a class="header-anchor" href="#adapting-the-profile" aria-label="Permalink to &quot;Adapting the profile&quot;">​</a></h1><p>Two private files adapt the harness to one user and one machine. Neither is in the repository.</p><ul><li><strong>The <a href="./concepts#profile">profile</a></strong> holds every value that names a person, an institution or a machine. Its path is <code>harness --profile F</code>, else <code>$RESEARCH_HARNESS_PROFILE</code>, else <code>~/.config/research-harness/profile.toml</code>.</li><li><strong>The model tables</strong> hold the model of each <a href="./concepts#tier">tier</a> for each <a href="./concepts#frontend">frontend</a>. Their path is <code>harness --models F</code>, else <code>$RESEARCH_HARNESS_MODELS</code>, else <code>models.toml</code> beside the profile.</li></ul><p>A third private file is optional: the <a href="#the-network-overlay">network overlay</a>, <code>network.toml</code> beside the profile, adds hosts to the network lists of Claude Code.</p><p><code>examples/profile.toml</code> and <code>examples/models.toml</code> show every key and every table, each with a comment that says what the value is. Copy them and write your values into the copies, as <a href="./setup-macos#the-profile-and-the-model-tables">setup-macos.md</a> shows. A template of the repository names a profile key as <code>{key}</code>, and a verb renders the template with the profile before it uses it. A template that names a key that the profile does not have stops the verb, and the message names the key.</p><h2 id="read-a-value" tabindex="-1">Read a value <a class="header-anchor" href="#read-a-value" aria-label="Permalink to &quot;Read a value&quot;">​</a></h2><p><code>harness get</code> prints the value of one key, one line for each item of a list. <code>harness render</code> prints a template rendered with the profile. Run these commands in the checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository_roots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launchagents/kaimon.plist</span></span></code></pre></div><p>Both verbs read every key that they name.</p><h2 id="the-keys-of-the-profile" tabindex="-1">The keys of the profile <a class="header-anchor" href="#the-keys-of-the-profile" aria-label="Permalink to &quot;The keys of the profile&quot;">​</a></h2><p>The table names each key of <code>examples/profile.toml</code> and the verbs that read it, beside <code>harness get</code> and <code>harness render</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">key</th><th style="text-align:left;">what it holds</th><th style="text-align:left;">read by</th></tr></thead><tbody><tr><td style="text-align:left;"><code>home</code></td><td style="text-align:left;">the home directory, an absolute path</td><td style="text-align:left;"><code>install</code> and <code>settings</code></td></tr><tr><td style="text-align:left;"><code>harness</code></td><td style="text-align:left;">the path of the checkout of this repository</td><td style="text-align:left;"><code>install</code>, in the OpenCode configuration</td></tr><tr><td style="text-align:left;"><code>memory_project</code></td><td style="text-align:left;">the name of the project directory of the research tree below <code>~/.claude/projects/</code>, which holds the memory</td><td style="text-align:left;"><code>install</code> and <code>settings</code>, in the settings template</td></tr><tr><td style="text-align:left;"><code>tree_agents</code></td><td style="text-align:left;">the directory of the <a href="./concepts#tree-instructions">tree instructions</a></td><td style="text-align:left;"><code>install</code>, which <a href="./concepts#install">installs</a> them into <code>~/.claude/</code></td></tr><tr><td style="text-align:left;"><code>launchd_prefix</code></td><td style="text-align:left;">the prefix of the labels of the launchd jobs in <code>launchagents/</code></td><td style="text-align:left;"><code>render</code> of the <code>launchagents/</code> templates; the update job <code>scripts/julia-update.jl</code></td></tr><tr><td style="text-align:left;"><code>autocommit_branch</code></td><td style="text-align:left;">the branch of the <code>origin</code> of <code>~/.claude</code> that <code>claude-autocommit</code> pushes to: <code>main</code> on the machine whose memory is the template, a branch of its own on each other machine. Optional: <code>render</code> gives <code>main</code> without it</td><td style="text-align:left;"><code>render</code> of <code>launchagents/claude-autocommit.plist</code> and <code>systemd/claude-autocommit.service</code></td></tr><tr><td style="text-align:left;"><code>org</code></td><td style="text-align:left;">the GitHub accounts and organisations where a <a href="./concepts#session">session</a> can open and comment on a pull request or an issue with no prompt</td><td style="text-align:left;"><code>install</code> and <code>settings</code>, in the settings template; <code>leaks</code>, which also searches for each of them</td></tr><tr><td style="text-align:left;"><code>repository_roots</code></td><td style="text-align:left;">the directories that hold the repositories of the research tree</td><td style="text-align:left;"><code>leaks</code>, which searches for the name of each directory below them</td></tr><tr><td style="text-align:left;"><code>docs_exceptions</code></td><td style="text-align:left;">the repositories that keep a documentation workflow of their own</td><td style="text-align:left;"><code>workflows</code>; <code>ci-protection</code>, through <code>githooks/verify-workflows.jl</code></td></tr><tr><td style="text-align:left;"><code>docs_additions</code></td><td style="text-align:left;">the repositories that add steps to the canonical documentation workflow</td><td style="text-align:left;"><code>workflows</code>; <code>ci-protection</code>, through <code>githooks/verify-workflows.jl</code></td></tr><tr><td style="text-align:left;"><code>protected_dir</code></td><td style="text-align:left;">the directories below <code>home</code> that no session can edit</td><td style="text-align:left;"><code>install</code>, in the settings template and the OpenCode configuration; <code>settings</code></td></tr><tr><td style="text-align:left;"><code>opencode_providers</code></td><td style="text-align:left;">the model servers of OpenCode beyond its own providers, one TOML table each, <code>[opencode_providers.&lt;name&gt;]</code>, written as the entries of the <code>provider</code> object. A string of JSONC lines, the earlier form, stops <code>install</code> with exit status 2</td><td style="text-align:left;"><code>install</code>, in the OpenCode configuration</td></tr><tr><td style="text-align:left;"><code>leak</code></td><td style="text-align:left;">the strings that must never appear in the repository</td><td style="text-align:left;"><code>leaks</code></td></tr></tbody></table><p><code>install</code> reads the settings template too, because it writes the permission layer of oh-my-pi from it. So each key of the settings template is a key that <code>install</code> reads.</p><p><code>leaks</code> also renders every template of the repository, but with <code>examples/profile.toml</code>, not with your profile. From your profile it reads only <code>leak</code>, <code>org</code> and <code>repository_roots</code>.</p><h2 id="the-tables-of-the-model-tables" tabindex="-1">The tables of the model tables <a class="header-anchor" href="#the-tables-of-the-model-tables" aria-label="Permalink to &quot;The tables of the model tables&quot;">​</a></h2><p>An <a href="./concepts#agent">agent</a> or a <a href="./concepts#skill">skill</a> names a tier in its <code>model:</code>: <code>large</code>, <code>medium</code> or <code>small</code>. Only <code>harness install</code> reads the model tables. It maps each tier to the model of each frontend.</p><table tabindex="0"><thead><tr><th style="text-align:left;">table</th><th style="text-align:left;">what it holds</th><th style="text-align:left;">read by</th></tr></thead><tbody><tr><td style="text-align:left;"><code>[claude]</code></td><td style="text-align:left;">the Claude Code model of each tier, written as the <code>model:</code> of the installed agent or skill; all three tiers are required</td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[models]</code></td><td style="text-align:left;">the OpenCode and oh-my-pi model of each tier, as <code>provider/model</code>; the <code>medium</code> model is also oh-my-pi&#39;s default model, in <code>harness.yml</code>, and oh-my-pi needs all three tiers</td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[model_overrides]</code></td><td style="text-align:left;">an agent whose model is not the model of its tier</td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[model_variants]</code></td><td style="text-align:left;">the <a href="./concepts#effort">effort</a> of every agent on one model: OpenCode&#39;s <code>variant:</code>, oh-my-pi&#39;s <code>thinking-level</code></td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[variants]</code></td><td style="text-align:left;">the effort of one agent or council seat, over the effort of its model</td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[reasoning_effort]</code></td><td style="text-align:left;">the effort of one agent or council seat, for a model that has no variant for it: OpenCode&#39;s <code>reasoningEffort:</code>, oh-my-pi&#39;s <code>thinking-level</code></td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[councils]</code></td><td style="text-align:left;">the copies of an agent on other models; one seat may add <code>verify = true</code>, and then it also judges each verify round</td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[context_limits]</code></td><td style="text-align:left;">the input tokens that a model may hold: a provider entry in <code>opencode.jsonc</code>, <code>contextWindow</code> in oh-my-pi&#39;s <code>models.yml</code></td><td style="text-align:left;"><code>install</code></td></tr><tr><td style="text-align:left;"><code>[opencode]</code>, <code>[omp]</code></td><td style="text-align:left;">the same sub-tables, such as <code>[omp.models]</code>; each key replaces the shared key for that frontend alone</td><td style="text-align:left;"><code>install</code></td></tr></tbody></table><p>OpenCode and oh-my-pi share every table but <code>[claude]</code>, so that their agents run on the same models.</p><p>A table that names a tier by an old name, <code>opus</code>, <code>sonnet</code> or <code>haiku</code>, stops <code>harness install</code> with exit 2, an error, and the message names the rename. <a href="./architecture#the-neutral-vocabulary">architecture.md</a> shows how each frontend reads a tier.</p><h2 id="the-network-overlay" tabindex="-1">The network overlay <a class="header-anchor" href="#the-network-overlay" aria-label="Permalink to &quot;The network overlay&quot;">​</a></h2><p>The settings template names no host. <code>settings/network.toml</code> holds the hosts of the harness, and the overlay <code>network.toml</code> beside the profile adds your own, such as the library resolver of your institution. The overlay is optional. <code>examples/network.toml</code> shows it. Both files have the same keys, and each key is optional in the overlay.</p><table tabindex="0"><thead><tr><th style="text-align:left;">key</th><th style="text-align:left;">what it holds</th><th style="text-align:left;">what the install writes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>allow</code></td><td style="text-align:left;">the hosts that the <code>WebFetch</code> tool and a sandboxed command can reach; write a host, never <code>*.X</code></td><td style="text-align:left;"><code>WebFetch(domain:X)</code> in <code>permissions.allow</code>; <code>X</code> in <code>sandbox.network.allowedDomains</code>, and <code>*.X</code> too when <code>X</code> is its own registrable domain</td></tr><tr><td style="text-align:left;"><code>infrastructure</code></td><td style="text-align:left;">the hosts that only a sandboxed command can reach, such as a package registry; <code>*.X</code> is allowed</td><td style="text-align:left;"><code>X</code> in <code>allowedDomains</code>, as written</td></tr><tr><td style="text-align:left;"><code>deny</code></td><td style="text-align:left;">the hosts that neither can reach; <code>*</code>, <code>*.X</code> and <code>X:port</code> are allowed</td><td style="text-align:left;"><code>X</code> in <code>sandbox.network.deniedDomains</code>; <code>WebFetch(domain:X)</code> in <code>permissions.deny</code>, except for an entry with a port</td></tr><tr><td style="text-align:left;"><code>[deny_reasons]</code></td><td style="text-align:left;">a reason for a <code>deny</code> entry, keyed by the exact entry</td><td style="text-align:left;"><code>sandbox.network.deniedDomainReasons</code>, which Claude Code shows the model when the <a href="./concepts#sandbox">sandbox</a> refuses the host</td></tr></tbody></table><p><code>install</code>, <code>render</code> of the settings template and <code>settings</code> read both files. A <code>deny</code> entry of either file removes each <code>allow</code> and <code>infrastructure</code> host that it matches from the generated allow lists. A <code>deny</code> entry with a port leaves the host on the allow lists. The sandbox refuses a host that no list names, with no prompt, because the template sets <code>strictAllowlist</code>. A <code>WebFetch</code> of such a host is on no list either, so it asks in the default permission mode. An entry that is a URL, a port outside <code>deny</code>, a host in <code>allow</code> and in <code>deny</code> of one file, and a key that the table does not name stop the verb with exit 2. So does the profile key <code>extra_domain</code>: move its hosts into the overlay&#39;s <code>allow</code>.</p><p>The lists apply to Claude Code only. OpenCode and oh-my-pi have no network allowlist.</p>`,24)])])}const y=t(l,[["render",s]]);export{p as __pageData,y as default};
